import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"الجدول الرئيسي لتقسيم العصور","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0070-纪元划分总表.md","filePath":"ar/0070-纪元划分总表.md"}'),l={name:"ar/0070-纪元划分总表.md"};function i(h,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="الجدول-الرئيسي-لتقسيم-العصور" tabindex="-1">الجدول الرئيسي لتقسيم العصور <a class="header-anchor" href="#الجدول-الرئيسي-لتقسيم-العصور" aria-label="Permalink to &quot;الجدول الرئيسي لتقسيم العصور&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>70</td></tr><tr><td>الوحدة</td><td>العصور التاريخية والأحداث الكبرى</td></tr><tr><td>الكلمات المفتاحية</td><td>تقسيم العصور، التقسيم التاريخي، الارتقاء البعدي بأربع مراحل، الخط الزمني، المحطات</td></tr></tbody></table><h2 id="أولاً-المبادئ-الأساسية-لتقسيم-العصور" tabindex="-1">أولاً: المبادئ الأساسية لتقسيم العصور <a class="header-anchor" href="#أولاً-المبادئ-الأساسية-لتقسيم-العصور" aria-label="Permalink to &quot;أولاً: المبادئ الأساسية لتقسيم العصور&quot;">​</a></h2><p>يتخذ تقسيم العصور التاريخية في كون هنغ يوان مسار الارتقاء البعدي بأربع مراحل إطاراً جوهرياً، ويرتكز على حالة تطور آلية المرساة بوصفها الأساس المحوري للتقسيم. كل عصر يقابل تحولاً جوهرياً في العلاقة بين الحضارة والكون؛ وحدود العصور ليست نقاطاً زمنية اعتباطية، بل تحددها أحداث كبرى ذات أهمية كونية.</p><p>يتبع تقسيم العصور ثلاثة مبادئ:</p><ul><li><strong>مبدأ مطابقة الارتقاء</strong>: كل عصر كبير يقابل مرحلة من مراحل الارتقاء البعدي الأربع، بينما تقابل الفترات الداخلية للعصر التقدمات الرئيسية في تلك المرحلة.</li><li><strong>مبدأ تحديد الأحداث</strong>: تحدد نقطتا بداية العصر ونهايته بأحداث كبرى رمزية، لا بتقسيم زمني متساوٍ بسيط.</li><li><strong>مبدأ حالة الحضارة</strong>: يُسمى كل عصر باسم الخصائص المحورية لحضارة تلك الفترة، بما يعكس التناقضات الرئيسية واتجاه التطور آنذاك.</li></ul><h2 id="ثانياً-الجدول-الرئيسي-للعصور-التاريخية-في-كون-هنغ-يوان" tabindex="-1">ثانياً: الجدول الرئيسي للعصور التاريخية في كون هنغ يوان <a class="header-anchor" href="#ثانياً-الجدول-الرئيسي-للعصور-التاريخية-في-كون-هنغ-يوان" aria-label="Permalink to &quot;ثانياً: الجدول الرئيسي للعصور التاريخية في كون هنغ يوان&quot;">​</a></h2><table tabindex="0"><thead><tr><th>رقم العصر</th><th>اسم العصر</th><th>مرحلة الارتقاء المقابلة</th><th>أحداث تحديد الحدود</th><th>الخصائص المحورية</th></tr></thead><tbody><tr><td>العصر الأول</td><td>عصر ما قبل المرساة</td><td>ما قبل الارتقاء البعدي</td><td>ولادة الكون ← صحوة الجيل الأول من المراسي</td><td>هيمنة الزراعة الافتراسية، انقطاعات حضارية متكررة</td></tr><tr><td>العصر الثاني</td><td>عصر صحوة المرساة</td><td>إطلاق تأسيس الواقع</td><td>صحوة المراسي من الجيل الأول ← توقيع الميثاق التكافلي</td><td>تأسيس آلية المرساة، بزوغ فكر مناهضة الافتراس</td></tr><tr><td>العصر الثالث</td><td>فترة تأسيس النظام التكافلي</td><td>تأسيس الواقع</td><td>توقيع الميثاق التكافلي ← الفتح الكامل لأنظمة الثلاثمائة</td><td>ترسيخ المؤسسات التكافلية، اكتمال إعادة البناء الاجتماعي</td></tr><tr><td>العصر الرابع</td><td>عصر فتح الأنظمة وتفعيلها</td><td>إطلاق التمكين التكنولوجي</td><td>فتح أنظمة الثلاثمائة ← اكتمال استراتيجية تفعيل 20٪</td><td>تعميم الزراعة، اختراقات في هندسة القوانين</td></tr><tr><td>العصر الخامس</td><td>عصر الارتقاء البعدي الأول</td><td>التمكين التكنولوجي ← تطور الوعي</td><td>نجاح الارتقاء البعدي الأول ← تأسيس جمهورية عشرة آلاف عرق</td><td>التحقق من ارتقاء الحضارة، اختراق واجهة مجال الوعي</td></tr><tr><td>العصر السادس</td><td>عصر جمهورية عشرة آلاف عرق</td><td>تطور الوعي</td><td>تأسيس جمهورية عشرة آلاف عرق ← إطلاق الاستكشاف عبر الأبعاد</td><td>توحيد مؤسسات الأعراق، تكافل الوعي الجماعي</td></tr><tr><td>العصر السابع</td><td>عصر الاستكشاف عبر الأبعاد</td><td>تطور الوعي ← التكافل بين النجوم</td><td>إطلاق الاستكشاف عبر الأبعاد ← الاكتمال الأولي للشبكة بين النجوم</td><td>اكتشافات عظيمة للأبعاد، توسع شبكة المراسي</td></tr><tr><td>العصر الثامن</td><td>عصر التكافل بين النجوم</td><td>التكافل بين النجوم</td><td>اكتمال الشبكة بين النجوم ← الارتقاء البعدي العام للكون</td><td>تكافل كوني للأعراق، الارتقاء البعدي للكون جارٍ</td></tr></tbody></table><h2 id="ثالثاً-الأطر-الزمنية-والمؤشرات-الرئيسية-لكل-عصر" tabindex="-1">ثالثاً: الأطر الزمنية والمؤشرات الرئيسية لكل عصر <a class="header-anchor" href="#ثالثاً-الأطر-الزمنية-والمؤشرات-الرئيسية-لكل-عصر" aria-label="Permalink to &quot;ثالثاً: الأطر الزمنية والمؤشرات الرئيسية لكل عصر&quot;">​</a></h2><p>بما أن كون هنغ يوان يحتوي أبعاداً متعددة تختلف بينها سرعات تدفق الزمن، تُعتمد الأطر الزمنية للعصور على الزمن المعياري للبعد الرئيسي:</p><table tabindex="0"><thead><tr><th>العصر</th><th>الإطار الزمني التقديري</th><th>تغطية المرساة</th><th>نسبة المزارعين</th><th>مؤشر التكافل</th></tr></thead><tbody><tr><td>عصر ما قبل المرساة</td><td>غير قابل للتحقق (بمقدار مليارات السنين)</td><td>0٪</td><td>&lt;0.01٪</td><td>&lt;10</td></tr><tr><td>عصر صحوة المرساة</td><td>آلاف السنين</td><td>1٪←10٪</td><td>0.01٪←1٪</td><td>10←30</td></tr><tr><td>فترة تأسيس النظام التكافلي</td><td>مئات السنين</td><td>10٪←40٪</td><td>1٪←10٪</td><td>30←50</td></tr><tr><td>عصر فتح الأنظمة وتفعيلها</td><td>مئات السنين</td><td>40٪←70٪</td><td>10٪←30٪</td><td>50←70</td></tr><tr><td>عصر الارتقاء البعدي الأول</td><td>عقود</td><td>70٪←85٪</td><td>30٪←50٪</td><td>70←80</td></tr><tr><td>عصر جمهورية عشرة آلاف عرق</td><td>مئات السنين</td><td>85٪←95٪</td><td>50٪←70٪</td><td>80←90</td></tr><tr><td>عصر الاستكشاف عبر الأبعاد</td><td>آلاف السنين</td><td>95٪←99٪</td><td>70٪←90٪</td><td>90←95</td></tr><tr><td>عصر التكافل بين النجوم</td><td>مستمر</td><td>←100٪</td><td>←100٪</td><td>←100</td></tr></tbody></table><p>تغطية المرساة هي نسبة المناطق الفرعية للأبعاد التي نُشر فيها عتاد المرساة؛ ونسبة المزارعين هي نسبة أشكال الحياة المشمولة بأنظمة الزراعة الرسمية؛ ومؤشر التكافل مؤشر شامل لقياس درجة تكافل الحضارة، وعلامته القصوى 100.</p><h2 id="رابعاً-المنطق-الداخلي-لتطور-العصور" tabindex="-1">رابعاً: المنطق الداخلي لتطور العصور <a class="header-anchor" href="#رابعاً-المنطق-الداخلي-لتطور-العصور" aria-label="Permalink to &quot;رابعاً: المنطق الداخلي لتطور العصور&quot;">​</a></h2><p>تطور العصور في كون هنغ يوان ليس تدفقاً زمنياً خطياً، بل عملية تطور حلزونية صاعدة. كل عصر، وهو يحل التناقضات المحورية التي خلفها العصر السابق، يهيئ في الوقت ذاته شروط تطور العصر التالي:</p><ul><li>كان التناقض الجوهري لعصر ما قبل المرساة تناقض الافتراس والتكافل، وقد أدى تطرفه إلى حتمية صحوة المرساة.</li><li>حل عصر صحوة المرساة مسألة «هل توجد المراسي»، لكنه واجه التحدي المؤسسي «لمن تخدم المراسي».</li><li>أتمت فترة تأسيس النظام التكافلي البناء المؤسسي، لكن احتكار موارد الزراعة ما زال يقيد تطور الجماهير.</li><li>كسر عصر فتح الأنظمة وتفعيلها احتكار الزراعة، لكن قفزة القدرات الفردية جلبت تحديات أخلاقية وأمنية جديدة.</li><li>تحقق عصر الارتقاء البعدي الأول من جدوى الارتقاء، لكن ارتقاء بعد واحد لم يكن كافياً لدفع التطور العام للكون.</li><li>وحد عصر جمهورية عشرة آلاف عرق مؤسسات الحضارة، لكن الكون ما زال يضم أبعاداً وأعراقاً كثيرة لم تُقترب بعد.</li><li>وسع عصر الاستكشاف عبر الأبعاد حدود الحضارة، لكن الأبعاد المتناثرة احتاجت روابط بين نجمية أوثق.</li><li>يشير عصر التكافل بين النجوم في نهاية المطاف إلى الهدف الأسمى للارتقاء البعدي العام للكون.</li></ul><h2 id="خامساً-تحديد-موقع-العصر-الحالي" tabindex="-1">خامساً: تحديد موقع العصر الحالي <a class="header-anchor" href="#خامساً-تحديد-موقع-العصر-الحالي" aria-label="Permalink to &quot;خامساً: تحديد موقع العصر الحالي&quot;">​</a></h2><p>وفقاً لحالة التطور الراهنة لكون هنغ يوان، تقف الحضارة عند المنعطف الحرج للانتقال من العصر الثالث (فترة تأسيس النظام التكافلي) إلى العصر الرابع (عصر فتح الأنظمة وتفعيلها). لقد ترسخت المؤسسات التكافلية في الأبعاد الرئيسية، وأعمال فتح أنظمة الثلاثمائة تتقدم في جميع الجوانب، ودخلت استراتيجية تفعيل 20٪ مرحلة التنفيذ. وقد انتقلت عدة تقنيات محورية من طبقة هندسة القوانين (محرك استنتاج ثمرة التضاعف، وأجهزة تسيير المبادئ القانونية المكانية، ونظام مرآة النسخ) من المختبر إلى الإنتاج الضخم.</p><p>المهمة المحورية لهذه الفترة الانتقالية: ضمان أن يصل فتح أنظمة الثلاثمائة بمنافعه فعلياً إلى جميع أشكال الحياة، مع إعداد الدفعة الأولى من قوى الأبعاد العليا عبر استراتيجية تفعيل 20٪، لتجميع ما يكفي من الطاقة والخبرة للارتقاء البعدي الأول.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>الجدول الرئيسي لتقسيم العصور هو الإطار الكلي لفهم التطور التاريخي لكون هنغ يوان. إنه يختزل التاريخ الطويل للكون في ثمانية عصور ذات منطق داخلي واضح، وكل عصر درجة ضرورية نحو الارتقاء البعدي العام للكون. وستفصل الوثائق اللاحقة كل عصر وما فيه من أحداث كبرى.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>71-前锚点时代 (عصر ما قبل المرساة)</li><li>72-锚点觉醒纪元 (عصر صحوة المرساة)</li><li>76-首次升维里程碑 (محطة الارتقاء البعدي الأول)</li></ul>',22)])])}const p=d(l,[["render",i]]);export{_ as __pageData,p as default};
